#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> a(6);
    for (int i = 0; i < 6; ++i) cin >> a[i];

    bool b = false;
    int c = 0;

    for (int i = 0; i <= 5; ++i) {
        int cnt = 0;
        for (int j = 0; j < 6; ++j) {
            if (a[j] == a[i]) cnt++;
        }
        if (cnt >= 4) {
            b = true;
            c = a[i];
            break;
        }
    }

    int s = 0;
    for (int i = 0; i <= 5; ++i) {
        if (a[i] == c) {
            a[i] = INT_MIN;
            s++;
        }
        if (s == 4) break;
    }

    if (b) {
        vector<int> comp;
        for (int i = 0; i < 6; ++i) {
            if (a[i] != INT_MIN) comp.push_back(a[i]);
        }
        if (comp.size() >= 2) {
            if (comp[0] == comp[1]) cout << "Elephant\n";
            else cout << "Bear\n";
        }
    } else {
        cout << "Alien\n";
    }

    return 0;
}

